import{_ as r,C as n,o as a,c as i,a2 as e,b as l,w as s,a as d,E as p,a3 as c}from"./chunks/framework.BC3NdntU.js";const B=JSON.parse('{"title":"2.5 合成与 GPU 加速","description":"","frontmatter":{},"headers":[],"relativePath":"卷二-浏览器工作原理/2.5-合成与GPU加速.md","filePath":"卷二-浏览器工作原理/2.5-合成与GPU加速.md","lastUpdated":1788852140000}'),h={name:"卷二-浏览器工作原理/2.5-合成与GPU加速.md"};function m(u,t,g,E,b,k){const o=n("Mermaid");return a(),i("div",null,[t[1]||(t[1]=e('<h1 id="_2-5-合成与-gpu-加速" tabindex="-1">2.5 合成与 GPU 加速 <a class="header-anchor" href="#_2-5-合成与-gpu-加速" aria-label="Permalink to &quot;2.5 合成与 GPU 加速&quot;">​</a></h1><blockquote><p>卷:卷二 · 浏览器工作原理 阅读时间:20min</p></blockquote><hr><h2 id="引言-为什么-transform-能-不重排不重绘-还快" tabindex="-1">引言:为什么 transform 能&quot;不重排不重绘&quot;还快 <a class="header-anchor" href="#引言-为什么-transform-能-不重排不重绘-还快" aria-label="Permalink to &quot;引言:为什么 transform 能&quot;不重排不重绘&quot;还快&quot;">​</a></h2><p><code>transform</code>/<code>opacity</code> 只在合成线程完成。这是做流畅动画、优化滚动的核心武器,也是&quot;合成层&quot;双刃剑的正确用法。要深挖,得懂&quot;层提升&quot;与&quot;Compositor Frame&quot;的机制。</p><hr><h2 id="一、属性代价分级-一图" tabindex="-1">一、属性代价分级(一图) <a class="header-anchor" href="#一、属性代价分级-一图" aria-label="Permalink to &quot;一、属性代价分级(一图)&quot;">​</a></h2>',7)),(a(),l(c,null,{default:s(()=>[p(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E4%BF%AE%E6%94%B9%E5%B1%9E%E6%80%A7%5D%20--%3E%20B%5B%E4%BB%85%E5%90%88%E6%88%90%3Cbr%2F%3Etransform%20%2F%20opacity%20%2F%20filter%5D%0A%20%20%20%20B%20--%3E%20B2%5B%E5%90%88%E6%88%90%E7%BA%BF%E7%A8%8B%2BGPU%2C%E8%B7%B3%E8%BF%87%E4%B8%BB%E7%BA%BF%E7%A8%8B%2C%E4%BB%A3%E4%BB%B7%E6%9C%80%E4%BD%8E%5D%0A%20%20%20%20A%20--%3E%20C%5B%E9%87%8D%E7%BB%98%3Cbr%2F%3Ecolor%20%2F%20background%5D%0A%20%20%20%20C%20--%3E%20C2%5B%E4%B8%BB%E7%BA%BF%E7%A8%8B%E7%BB%98%E5%88%B6%2C%E4%B8%8D%E5%B8%83%E5%B1%80%5D%0A%20%20%20%20A%20--%3E%20D%5B%E9%87%8D%E6%8E%92%3Cbr%2F%3Eleft%20%2F%20top%20%2F%20width%5D%0A%20%20%20%20D%20--%3E%20D2%5B%E4%B8%BB%E7%BA%BF%E7%A8%8B%E5%85%A8%E9%93%BE%E8%B7%AF%3A%E5%B8%83%E5%B1%80%E2%86%92%E7%BB%98%E5%88%B6%E2%86%92%E5%90%88%E6%88%90%5D%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<table tabindex="0"><thead><tr><th>属性</th><th>阶段</th><th>主线程</th><th>代价</th></tr></thead><tbody><tr><td><code>left/top</code></td><td>布局→绘制→合成</td><td>✅</td><td>高</td></tr><tr><td><code>color</code></td><td>绘制→合成</td><td>✅</td><td>中</td></tr><tr><td><code>transform/opacity</code></td><td><strong>仅合成</strong></td><td>❌</td><td><strong>最低</strong></td></tr></tbody></table><hr><h2 id="二、为什么-transform-opacity-能绕过主线程-深层" tabindex="-1">二、为什么 transform/opacity 能绕过主线程(深层) <a class="header-anchor" href="#二、为什么-transform-opacity-能绕过主线程-深层" aria-label="Permalink to &quot;二、为什么 transform/opacity 能绕过主线程(深层)&quot;">​</a></h2><ul><li>它们只改变&quot;<strong>像素的几何变换/透明度</strong>&quot;,不改变布局几何、不改变内容</li><li>因此被设计成只在合成阶段处理,而合成线程<strong>不碰 JS/布局</strong>、可独立并行</li><li>产物是 <strong>Compositor Frame</strong>:各图层位图 + 变换/透明度/层级,交 GPU 上屏</li></ul><blockquote><p>所以改 <code>transform: translateX(10px)</code>,只是&quot;重发一个带新偏移的 Compositor Frame&quot;,<strong>布局、绘制、甚至主线程都不动</strong>。</p></blockquote><hr><h2 id="三、层提升-layer-promotion-的判定" tabindex="-1">三、层提升(Layer Promotion)的判定 <a class="header-anchor" href="#三、层提升-layer-promotion-的判定" aria-label="Permalink to &quot;三、层提升(Layer Promotion)的判定&quot;">​</a></h2><div class="language-css vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transform: translateZ(0);        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 3D 变换 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">will-change</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: transform, opacity; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 显式预告 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">backdrop-filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">video</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">canvas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / iframe;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">position: fixed / sticky;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>深层:层提升为什么经常伴随&quot;新的层叠上下文/包含块&quot;?</strong> 一个元素被提升为合成层,常需<strong>独立的绘制与定位基准</strong>(重算包含块,见 <a href="/frontend-knowledge-base/卷三-HTML与CSS/3.2-盒模型与包含块.html">3.2</a>),所以 <code>transform</code>/<code>filter</code> 会&quot;劫持&quot;后代的包含块——这就是 3.2 里&quot;transform 偷走 fixed 包含块&quot;的底层原因。</p><hr><h2 id="四、双刃剑-层爆炸" tabindex="-1">四、双刃剑:层爆炸 <a class="header-anchor" href="#四、双刃剑-层爆炸" aria-label="Permalink to &quot;四、双刃剑:层爆炸&quot;">​</a></h2><ul><li>每层要独立<strong>位图内存</strong>,层越多内存越大</li><li>每层要独立<strong>光栅化</strong>,层巨多/超大反而拖慢</li><li><strong>隐式提升</strong>:一层被提升,重叠元素可能被连带提升 → 雪球式&quot;层爆炸&quot;</li></ul><p><strong>合理用法</strong>:只给真正会动的元素;动画结束移除 <code>will-change</code>;DevTools→Layers 面板测图层数量/内存再优化。</p><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>属性分级:left/top(布局)&gt; color(绘制)&gt; transform/opacity(仅合成)</span></span>
<span class="line"><span>深层:仅合成=重发 Compositor Frame,不动布局/绘制/主线程</span></span>
<span class="line"><span>层提升:transform/will-change/filter/video/sticky</span></span>
<span class="line"><span>风险:层爆炸(内存↑光栅化↑)→ 只给必要元素,先测再优化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="六、面试题" tabindex="-1">六、面试题 <a class="header-anchor" href="#六、面试题" aria-label="Permalink to &quot;六、面试题&quot;">​</a></h2><p><strong>Q1:<code>will-change</code> 是什么?为什么不能滥用?</strong></p><p>提前告诉浏览器&quot;该元素即将变化&quot;,使其<strong>预提升合成层</strong>,动画开始不卡顿。不能滥用:长期占用图层内存,大量使用导致层爆炸、内存飙升;应只在即将动画的元素上、结束后移除。</p><p><strong>Q2:滚动性能为什么推荐&quot;合成层滚动&quot;而非 JS 改 top?</strong></p><p>原生滚动在合成线程直接移位图、重发 Compositor Frame,不动布局;JS 在 <code>scroll</code> 里改 <code>top/left</code> 会触发一串重排。正确:原生滚动 + <code>position: sticky</code>/<code>transform</code>。</p><p><strong>Q3:一个元素动画只改 <code>opacity</code>,会触发布局和绘制吗?</strong></p><p>不会。<code>opacity</code> 是纯合成属性,只重发 Compositor Frame,布局、绘制都不重来,全程合成线程+GPU。</p><p><strong>Q4:为什么有时候&quot;给元素加 transform 后,里面 fixed 定位的元素跑偏了&quot;?</strong></p><p>transform 会让元素<strong>成为合成层并建立新的包含块</strong>(见 <a href="/frontend-knowledge-base/卷三-HTML与CSS/3.2-盒模型与包含块.html">3.2</a>),内部 <code>fixed</code> 后代改以它为参照,不再相对视口,于是&quot;跑偏&quot;。这是层提升与包含块机制的联动。</p><p><strong>Q5:如何判断一个页面是否&quot;层爆炸&quot;?</strong></p><p>DevTools → <strong>Layers</strong> 面板,看合成层数量与各层内存。若图层异常多、大量元素被隐式提升(尤其一堆 <code>will-change</code>),就是层爆炸信号;据此清理无必要的 <code>will-change</code>/<code>translateZ(0)</code>。</p><p><strong>Q6:<code>will-change</code> 和直接写 <code>transform: translateZ(0)</code> 都能提升层,有何区别?</strong></p><p>后者是&quot;<strong>持续</strong>&quot;把元素固定成层(一直占用内存);<code>will-change</code> 是&quot;<strong>预告</strong>&quot;即将变化(浏览器按需预提升),更适合&quot;动画期间开、结束关&quot;。工程上 <code>will-change</code> 更可控。</p><hr><p>📎 参考:Google Web Fundamentals《合成与绘制》、Chrome DevTools Layers 文档、chromium Compositor 文档</p><p>📎 权威延伸阅读:</p><ul><li>《Animations: Compositing》(web.dev) <a href="https://web.dev/articles/animations-guide" target="_blank" rel="noreferrer">https://web.dev/articles/animations-guide</a></li><li>《Rendering performance》(web.dev) <a href="https://web.dev/articles/rendering-performance" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-performance</a></li><li>《GPU accelerated compositing in Chrome》(Chromium) <a href="https://www.chromium.org/developers/design-documents/gpu-accelerated-compositing-in-chrome/" target="_blank" rel="noreferrer">https://www.chromium.org/developers/design-documents/gpu-accelerated-compositing-in-chrome/</a></li></ul>`,34))])}const q=r(h,[["render",m]]);export{B as __pageData,q as default};
